package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import android.content.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
@androidx.media3.common.util.UnstableApi
public class PlaylistPickerTest {
 @Test public void fixedCounterAndMarksSurviveRecycledRows()throws Exception{
  android.app.Instrumentation ins=getInstrumentation();android.content.Context context=ins.getTargetContext();DownloadsActivity activity=(DownloadsActivity)ins.startActivitySync(new Intent(context,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PlaylistPicker[] picker={null};AtomicInteger requested=new AtomicInteger();int[] top={0},unchecked={0};
  try{ins.runOnMainSync(()->{List<YoutubeDownloads.Entry> entries=new ArrayList<>();for(int i=0;i<1500;i++)entries.add(new YoutubeDownloads.Entry("Vídeo "+i,"https://www.youtube.com/watch?v="+String.format(Locale.ROOT,"%011d",i),"",125+i));PlaylistSelection s=new PlaylistSelection(entries);picker[0]=new PlaylistPicker(activity,"Seleção de teste",s,()->{},()->requested.set(s.count()));activity.setContentView(picker[0].root);});ins.waitForIdleSync();
   ins.runOnMainSync(()->{assertEquals("Baixar (0)",picker[0].download.getText().toString());assertFalse(picker[0].download.isEnabled());picker[0].all.performClick();assertEquals(1500,picker[0].selection.count());top[0]=picker[0].download.getTop();picker[0].list.setSelection(1499);});ins.waitForIdleSync();
   ins.runOnMainSync(()->{unchecked[0]=picker[0].list.getFirstVisiblePosition();assertTrue(unchecked[0]>0);CheckBox box=(CheckBox)picker[0].list.getChildAt(0).findViewWithTag("playlist-check");box.performClick();assertEquals(1499,picker[0].selection.count());assertEquals(top[0],picker[0].download.getTop());picker[0].list.setSelection(0);});ins.waitForIdleSync();
   ins.runOnMainSync(()->{assertFalse(picker[0].selection.contains(unchecked[0]));assertTrue(picker[0].selection.contains(0));assertEquals("Baixar (1499)",picker[0].download.getText().toString());picker[0].clear.performClick();assertEquals(0,picker[0].selection.count());});ins.waitForIdleSync();
   ins.runOnMainSync(()->{CheckBox box=(CheckBox)picker[0].list.getChildAt(0).findViewWithTag("playlist-check");box.performClick();assertEquals(1,picker[0].selection.count());picker[0].download.performClick();assertEquals(1,requested.get());assertTrue(picker[0].download.getBottom()<=picker[0].root.getHeight());});
  }finally{ins.runOnMainSync(()->{if(picker[0]!=null)picker[0].close();activity.finish();});ins.waitForIdleSync();}
 }
 private static Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private static void field(Object o,String name,Object value)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 @Test public void largeSelectionUsesPrivateSnapshotAndSurvivesActivityRecreation()throws Exception{
  android.app.Instrumentation ins=getInstrumentation();Context c=ins.getTargetContext();DownloadsActivity first=(DownloadsActivity)ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));android.app.Activity[] current={first};android.os.Bundle saved=new android.os.Bundle();String[] token={null};android.app.Instrumentation.ActivityMonitor monitor=ins.addMonitor(DownloadsActivity.class.getName(),null,false);
  try{ins.runOnMainSync(()->{try{List<YoutubeDownloads.Entry> entries=new ArrayList<>();String title=String.join("",Collections.nCopies(150,"A"));for(int i=0;i<5000;i++)entries.add(new YoutubeDownloads.Entry(title,"https://www.youtube.com/watch?v="+String.format(Locale.ROOT,"%011d",i)));PlaylistSelection selected=new PlaylistSelection(entries);selected.set(0,true);selected.set(4999,true);field(first,"selectionState",selected);field(first,"playlistItems",selected.items);java.lang.reflect.Method render=DownloadsActivity.class.getDeclaredMethod("renderPlaylist");render.setAccessible(true);render.invoke(first);ins.callActivityOnSaveInstanceState(first,saved);token[0]=saved.getString("selection_file");assertNotNull(token[0]);String raw=DownloadSnapshots.read(c,token[0]);assertTrue(raw.length()>1000000);assertEquals(5000,PlaylistSelection.decode(raw).items.size());String queue=DownloadSnapshots.write(c,DownloadQueue.encode(entries));try{assertEquals(5000,DownloadQueue.validate(DownloadSnapshots.read(c,queue)).length());}finally{DownloadSnapshots.remove(c,queue);}android.os.Parcel parcel=android.os.Parcel.obtain();try{parcel.writeBundle(saved);assertTrue(parcel.dataSize()<64000);}finally{parcel.recycle();}first.recreate();}catch(Exception e){throw new RuntimeException(e);}});
   android.app.Activity restored=monitor.waitForActivityWithTimeout(15000);assertNotNull(restored);current[0]=restored;ins.waitForIdleSync();ins.runOnMainSync(()->{try{PlaylistSelection value=(PlaylistSelection)field(restored,"selectionState");assertNotNull(value);assertEquals(5000,value.items.size());assertEquals(2,value.count());assertTrue(value.contains(4999));assertNotNull(field(restored,"picker"));}catch(Exception e){throw new RuntimeException(e);}});try{DownloadSnapshots.read(c,"../outside");fail();}catch(java.io.IOException expected){}
  }finally{ins.removeMonitor(monitor);ins.runOnMainSync(()->{if(current[0]!=null)current[0].finish();if(!first.isDestroyed())first.finish();});DownloadSnapshots.remove(c,token[0]);ins.waitForIdleSync();}
 }
}
